# Find marker positions
idx_7_orig = np.argwhere(input_arr == 7)

# BFS to find all 0s reachable from markers
def get_neighbors(r, c):
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            yield nr, nc

visited = set()
queue = []

for r in range(rows):
    for c in range(cols):
        if input_arr[r][c] == 7:
            queue.append((r,c))
            visited.add((r,c))

idx = 0
while idx < len(queue):
    cr, cc = queue[idx]
    idx += 1

    for nr, nc in get_neighbors(cr, cc):
        if input_arr[nr][nc] == 0 and (nr, nc) not in visited:
            visited.add((nr, nc))
            queue.append((nr, nc))

# Create output grid
output_arr = input_arr.copy().tolist()
changed_count = 0
for pos in sorted(visited):
    r, c = pos
    if input_arr[r][c] == 0:
        output_arr[r][c] = 7
        changed_count += 1

print(f"Changed {changed_count} cells")
print(f"\nOutput grid shape: {rows} x {cols}")
print(f"Unique values: {sorted(np.unique(output_arr))}")

# Print changed positions
