changes = []
for r in range(rows):
    for c in range(cols):
        if output_arr[r][c] != input_list[r][c]:
            changes.append(((r,c), input_list[r][c], output_arr[r][c]))

print("\nChanged positions:")
for pos in sorted(changes):
    print(f"  {pos}: {pos[1]} -> {pos[2]}")

